{"summary": "API tests for click recording and stats, repository tests for ordering.", "files": [{"path": "tests/UrlShortener.Tests/Api/ClickAnalyticsTests.cs", "content": "using System.Net;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc.Testing;

namespace UrlShortener.Tests.Api;

public sealed class ClickAnalyticsTests : IAsyncLifetime
{
    private readonly ShortenerApiFactory _factory = new();
    private HttpClient _client = null!;

    public async Task InitializeAsync()
    {
        await _factory.InitializeDatabaseAsync();
        _client = _factory.CreateClient(new WebApplicationFactoryClientOptions { AllowAutoRedirect = false });
    }

    public async Task DisposeAsync()
    {
        _client.Dispose();
        await _factory.DisposeAsync();
    }

    [Fact]
    public async Task Redirect_records_referrer_and_user_agent_in_stats()
    {
        await _client.PostAsJsonAsync("/api/links", new { url = "https://example.com", alias = "tracked" });
        using var request = new HttpRequestMessage(HttpMethod.Get, "/tracked");
        request.Headers.Referrer = new Uri("https://news.example.org/article");
        request.Headers.UserAgent.ParseAdd("TestBrowser/1.0");

        Assert.Equal(HttpStatusCode.Found, (await _client.SendAsync(request)).StatusCode);
        var stats = await _client.GetFromJsonAsync<StatsDto>("/api/links/tracked/stats");

        var click = Assert.Single(stats!.RecentClicks);
        Assert.Equal("https://news.example.org/article", click.Referrer);
        Assert.Equal("TestBrowser/1.0", click.UserAgent);
        Assert.True(click.OccurredAt > DateTimeOffset.UtcNow.AddMinutes(-5));
        Assert.Equal(1, stats.ClickCount);
    }

    [Fact]
    public async Task Click_without_headers_is_recorded_with_nulls()
    {
        await _client.PostAsJsonAsync("/api/links", new { url = "https://example.com", alias = "bare" });

        await _client.GetAsync("/bare");
        var stats = await _client.GetFromJsonAsync<StatsDto>("/api/links/bare/stats");

        var click = Assert.Single(stats!.RecentClicks);
        Assert.Null(click.Referrer);
    }

    [Fact]
    public async Task Stats_return_only_the_ten_most_recent_clicks_newest_first()
    {
        await _client.PostAsJsonAsync("/api/links", new { url = "https://example.com", alias = "busy" });
        for (var i = 1; i <= 12; i++)
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, "/busy");
            request.Headers.Referrer = new Uri($"https://ref.example/{i}");
            await _client.SendAsync(request);
        }

        var stats = await _client.GetFromJsonAsync<StatsDto>("/api/links/busy/stats");

        Assert.Equal(12, stats!.ClickCount);
        Assert.Equal(10, stats.RecentClicks.Count);
        Assert.Equal("https://ref.example/12", stats.RecentClicks[0].Referrer);
        Assert.Equal("https://ref.example/3", stats.RecentClicks[^1].Referrer);
    }

    private sealed record StatsDto(string Code, long ClickCount, List<ClickDto> RecentClicks);

    private sealed record ClickDto(DateTimeOffset OccurredAt, string? Referrer, string? UserAgent);
}
