using UrlShortener.Infrastructure.Persistence;

namespace UrlShortener.Tests.Infrastructure;

public sealed class EfClickRepositoryTests : IDisposable
{
    private readonly SqliteDatabase _database = new();
    private readonly CancellationToken _ct = CancellationToken.None;

    [Fact]
    public async Task Recent_returns_clicks_for_the_link_newest_first()
    {
        await using var context = _database.CreateContext();
        await new EfLinkRepository(context).AddAsync(new Link { Code = "abc1234", LongUrl = "https://example.com", CreatedAt = DateTimeOffset.UnixEpoch }, _ct);
        var link = context.Links.Single();
        var clicks = new EfClickRepository(context);

        for (var i = 1; i <= 3; i++)
        {
            await clicks.RecordAsync(new Click { LinkId = link.Id, OccurredAt = DateTimeOffset.UnixEpoch.AddMinutes(i), Referrer = $"r{i}" }, _ct);
        }

        var recent = await clicks.RecentAsync(link.Id, 2, _ct);

        Assert.Equal(["r3", "r2"], recent.Select(c => c.Referrer));
    }

    [Fact]
    public async Task Recent_is_empty_for_a_link_without_clicks()
    {
        await using var context = _database.CreateContext();

        Assert.Empty(await new EfClickRepository(context).RecentAsync(42, 10, _ct));
    }

    public void Dispose() => _database.Dispose();
}
